import numpy as np

def process_datasets(datasets, key_prefix, min_value, max_value):
    """
    Process a list of datasets (pandas DataFrames), adding a new column of
    random values within [min_value, max_value) to each one.

    Each new column is named uniquely per dataset using the pattern
    "<key_prefix>_<index>", guaranteeing no naming conflicts across datasets
    in the returned list.

    Parameters
    ----------
    datasets : list
        A list of pandas DataFrame objects.
    key_prefix : str
        Prefix used to construct the new column names.
    min_value : number
        Lower bound (inclusive) of the random values.
    max_value : number
        Upper bound (exclusive) of the random values.

    Returns
    -------
    list of pandas.DataFrame
        The list of updated datasets, each with the new random column.

    Raises
    ------
    TypeError
        If `datasets` is not a list, or if any element is not a
        pandas DataFrame.
    """
    if not isinstance(datasets, (list, tuple)):
        raise TypeError(
            "datasets must be a list of pandas DataFrames, got {}".format(
                type(datasets).__name__
            )
        )

    updated_datasets = []

    for index, dataset in enumerate(datasets):
        if not isinstance(dataset, pd.DataFrame):
            raise TypeError(
                "Dataset at index {} is not a pandas DataFrame (got {}).".format(
                    index, type(dataset).__name__
                )
            )

        # Build a unique column name for this dataset.
        new_column_name = "{}_{}".format(key_prefix, index)
        while new_column_name in dataset.columns:
            new_column_name += "_x"

        # Work on a copy so the original input DataFrames are not mutated.
        dataset = dataset.copy()
        dataset[new_column_name] = np.random.uniform(
            min_value, max_value, size=len(dataset)
        )

        updated_datasets.append(dataset)

    return updated_datasets
